// Percentual do valor total do contrato retido como retainage (garantia até a entrega).
const RETAINAGE_RATE = 0.1


function money(value: number) { return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value) }
// Converte valores digitados em formatos "1.234,56" (pt-BR) ou "1,234.56" (en-US) para número.
function parseAmount(input: string | number | null | undefined) {
  let raw = String(input ?? '').replace(/[^0-9.,-]/g, '')
  if (!raw) return 0
  const negative = raw.startsWith('-')
  raw = raw.replace(/-/g, '')
  const lastSep = Math.max(raw.lastIndexOf(','), raw.lastIndexOf('.'))
  let integerPart = raw
  let fraction = ''
  if (lastSep > -1 && raw.length - lastSep - 1 <= 2) { integerPart = raw.slice(0, lastSep); fraction = raw.slice(lastSep + 1) }
  const value = Number(fraction ? `${integerPart.replace(/[.,]/g, '')}.${fraction}` : integerPart.replace(/[.,]/g, '')) || 0
  return negative ? -value : value
}
// Formata uma data ISO (yyyy-mm-dd) para dd/mm/aaaa.
function formatDateBR(value: string | null | undefined) {
  if (!value) return ''
  const [year, month, day] = value.slice(0, 10).split('-')
  return year && month && day ? `${day}/${month}/${year}` : value
}

